<?php
require __DIR__.'/programaciones-common.php';
$id=prog_id($_GET,'id_plantilla');$template=prog_template($id);
$courses=app_rows('SELECT id_curso,nombre,fecha_inicio,fecha_fin FROM cursos_academicos ORDER BY fecha_inicio DESC');
$course=prog_id($_GET,'curso_seleccionado',true);if(!$course){foreach($courses as $candidate)if($candidate['fecha_inicio']<=date('Y-m-d')&&$candidate['fecha_fin']>=date('Y-m-d')){$course=(int)$candidate['id_curso'];break;}if(!$course)$course=(int)($courses[0]['id_curso']??0);}
$groups=app_rows('SELECT g.id_grupo,g.dia,g.hora_inicio,g.hora_fin,s.id_subgrupo,s.bloqueado,t.nombre_tipo_grupo FROM aulas_grupos g JOIN aulas_grupos_subgrupos s ON s.id_grupo=g.id_grupo AND s.id_subgrupo<g.num_subgrupos LEFT JOIN aulas_grupos_tipos t ON t.id_tipo_grupo=s.tipo_subgrupo WHERE g.id_curso=? ORDER BY g.dia,g.hora_inicio,s.id_subgrupo','i',[$course]);
$days=[1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo'];
prog_header('Asignar programación',(string)$template['descripcion'].' · '.prog_level($template['nivel']));?>
<a class="prog-back" href="gestion_plantillas.php?id_plantilla=<?=$id?>">← Volver a la programación</a>
<section class="prog-panel prog-details"><form method="get" action="vincular_plantilla.php" class="prog-form-grid"><input type="hidden" name="id_plantilla" value="<?=$id?>"><label>Curso<select name="curso_seleccionado"><?php foreach($courses as $c){?><option value="<?=(int)$c['id_curso']?>" <?=(int)$c['id_curso']===$course?'selected':''?>><?=app_escape($c['nombre'])?></option><?php }?></select></label><div><button type="submit" class="prog-button secondary">Ver grupos del curso</button></div></form></section>
<section class="prog-panel prog-details prog-assignments"><h2>Grupo y fecha de inicio</h2><?php if(!$groups){?><div class="prog-empty">No hay grupos disponibles para este curso.</div><?php }else{?><form method="post" action="vincular_plantilla1.php"><input type="hidden" name="id_plantilla" value="<?=$id?>"><label>Grupo<select name="grupo" required><option value="">Selecciona un horario y subgrupo</option><?php foreach($groups as $g){?><option value="<?=(int)$g['id_grupo']?>_<?=(int)$g['id_subgrupo']+1?>" <?=!empty($g['bloqueado'])?'disabled':''?>><?=app_escape(($days[(int)$g['dia']]??'Día sin definir').' · '.substr($g['hora_inicio'],0,5).'–'.substr($g['hora_fin'],0,5).' · Subgrupo '.((int)$g['id_subgrupo']+1).' · '.($g['nombre_tipo_grupo']?:'Sin nivel'))?><?=!empty($g['bloqueado'])?' (bloqueado)':''?></option><?php }?></select></label><label>Fecha de la primera clase<input type="date" name="fecha_inicio" value="<?=date('Y-m-d')?>" required></label><p class="prog-muted">Elige una fecha del curso que coincida con el día de clase. No se sustituirán otras programaciones que ya tenga el grupo.</p><button type="submit" class="prog-button">Asignar programación</button></form><?php }?></section>
<?php prog_footer(); ?>